   * @param w 物品的重量数组
   * @param p 物品的价值数组
   * @return 装满背包的最大价值
   */
  public static int getResult(int bag, int n, int[] w, int[] p) {
    // dp[i]表示装满承重为 i 的背包的最大价值
    int[] dp = new int[bag + 1];

    // 装满背包的背包问题，初始化时需要将除了dp[0]外的dp元素值设为负无穷
    Arrays.fill(dp, Integer.MIN_VALUE);
    dp[0] = 0;

