      for (int j = w[i]; j <= bag; j++) { // 遍历背包承重，完全背包这里要正序遍历
        dp[j] = Math.max(dp[j], dp[j - w[i]] + p[i]);
      }
    }

    // 返回装满承重为bag的背包的最大价值
    return dp[bag];
  }
}

